package com.brainserve.onboarding.forms.domain.model;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="form_answers",schema="client_onboarding")
public class FormAnswer { @Id private UUID id; @Column(name="organization_id",nullable=false) private UUID organizationId; @Column(name="submission_id",nullable=false) private UUID submissionId; @Column(name="field_id",nullable=false) private UUID fieldId; @JdbcTypeCode(SqlTypes.JSON) @Column(name="value_json",nullable=false,columnDefinition="jsonb") private JsonNode valueJson; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Version private long version; protected FormAnswer(){} public FormAnswer(UUID id,UUID org,UUID submission,UUID field,JsonNode value,Instant now){this.id=id;organizationId=org;submissionId=submission;fieldId=field;valueJson=value.deepCopy();createdAt=now;updatedAt=now;} public void update(JsonNode value,Instant now){valueJson=value.deepCopy();updatedAt=now;} public UUID getId(){return id;} public UUID getSubmissionId(){return submissionId;} public UUID getFieldId(){return fieldId;} public JsonNode getValueJson(){return valueJson.deepCopy();} public long getVersion(){return version;} }
